import{_ as e,o as d,c as o,aj as r}from"./framework.js";const u=JSON.parse('{"title":"k.net | Net | KScript API","description":"k.net provides network-related capabilities in site scripts, divided by sub-modules:","frontmatter":{"title":"k.net | Net | KScript API","description":"k.net provides network-related capabilities in site scripts, divided by sub-modules:","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/api/net/index.html"}]]},"headers":[],"relativePath":"api/net/index.md","filePath":"en/api/net/index.md","lastUpdated":1787542634000}'),n={name:"api/net/index.md"};function i(a,t,s,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="k-net" tabindex="-1">k.net <a class="header-anchor" href="#k-net" aria-label="Permalink to &quot;k.net&quot;">​</a></h1><blockquote><p>HTTP, WebSocket, DNS, IP, and remote connections</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>k.net</code> provides network-related capabilities in site scripts, divided by sub-modules:</p><table tabindex="0"><thead><tr><th>submodule</th><th>path</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./httpclient.html">httpClient</a></td><td><code>k.net.httpClient</code></td><td>Recommended: proxy forwarding, JSON/form/multipart, <code>send</code> unified request</td></tr><tr><td><a href="./url.html">url</a></td><td><code>k.net.url</code></td><td>Simple synchronization HTTP; suitable for quickly pulling binaries (such as images)</td></tr><tr><td><a href="./websocket.html">webSocket</a></td><td><code>k.net.webSocket</code></td><td>Upgrade the current request to WebSocket and manage the connection</td></tr><tr><td><a href="./dns.html">DNS</a></td><td><code>k.net.DNS</code></td><td>Parse A/MX/NS, reverse DNS, Whois (note case)</td></tr><tr><td><a href="./ip.html">IP</a></td><td><code>k.net.IP</code></td><td>Current request IP, IP geographic information (note case)</td></tr><tr><td><a href="./ping.html">ping</a></td><td><code>k.net.ping</code></td><td>Probe ICMP connectivity and round-trip time</td></tr><tr><td><a href="./sshClient.html">sshClient</a></td><td><code>k.net.sshClient</code></td><td>Execute commands over SSH</td></tr><tr><td><a href="./sftpClient.html">sftpClient</a></td><td><code>k.net.sftpClient</code></td><td>Upload and download files over SFTP</td></tr><tr><td><a href="./telnetClient.html">telnetClient</a></td><td><code>k.net.telnetClient</code></td><td>Read and write Telnet sessions</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">selection: httpClient and url</p><table tabindex="0"><thead><tr><th>scene</th><th>suggestion</th></tr></thead><tbody><tr><td>API proxy, with custom Header/Body, multipart upload</td><td><strong><code>k.net.httpClient</code></strong></td></tr><tr><td>Batch download, need <code>KHttpResponse.save</code> to download</td><td><strong><code>k.net.httpClient</code></strong> (including batch)</td></tr><tr><td>Fast GET remote <strong>image/file binary</strong></td><td><strong><code>k.net.url.getAsBinary(url)</code></strong></td></tr><tr><td>One line GET string or JSON</td><td><code>k.net.url.get</code> / <code>k.net.url.getJson</code></td></tr></tbody></table></div><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../file/file.html">k.file</a> — site disk file (different from outbound HTTP)</li><li><a href="./../request/">k.request</a> — Current inbound request</li><li><a href="./../utils/">k.utils</a> — General utilities such as byte encoding conversion</li></ul>',8)])])}const k=e(n,[["render",i]]);export{u as __pageData,k as default};
